#[tauri::command]
pub async fn cmd_notification_get_permission_status<R: Runtime>(
    app: AppHandle<R>,
) -> Result<NotificationPermissionStatusDto, IpcError> {
    run_blocking(move || Ok(service_for(&app).permission_status())).await
}

